+    private static void InspectPruningSources(CombatRootSnapshot root, CombatState live, string outputDirectory)
+    {
+        var rootField = typeof(CombatRootSnapshot).GetField("_rootSimulator", BindingFlags.Instance | BindingFlags.NonPublic)
+            ?? throw new InvalidOperationException("Root simulator field is unavailable.");
+        var simulator = (CombatSolver.Engine.InCombat.Simulation.CombatPredictionSimulator)rootField.GetValue(root)!;
+        var combat = (SimulatedCombatState)simulator.State.CombatState;
+        var player = root.PlayerIdentity;
+        string stateBefore = ContinuationStamp.CapturePredicted(player, simulator, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText;
+        bool Existing(string method, object source, bool reviewedArgument)
+        {
+            MethodInfo m = typeof(StrategicHpRecoveryBound).GetMethod(method, BindingFlags.Static | BindingFlags.NonPublic)
+                ?? throw new InvalidOperationException("Missing source predicate: " + method);
+            return (bool)m.Invoke(null, reviewedArgument ? [source, true] : [source])!;
+        }
+        object Describe(MegaCrit.Sts2.Core.Models.AbstractModel source, string location, int index)
+        {
+            Type type = source.GetType();
+            bool? typeAccepted = source switch
+            {
+                MegaCrit.Sts2.Core.Models.CardModel c => Existing("ComponentInitialCard", c, true),
+                MegaCrit.Sts2.Core.Models.RelicModel => Existing("ComponentRelic", type, true),
+                MegaCrit.Sts2.Core.Models.PowerModel => Existing("ComponentPower", type, true),
+                MegaCrit.Sts2.Core.Models.MonsterModel => Existing("ComponentEnemy", type, true),
+                MegaCrit.Sts2.Core.Models.PotionModel => Existing("ComponentPotion", type, false),
+                _ => null,
+            };
+            return new { location, index, sourceType = type.FullName, sourceName = type.Name, id = source.Id.Entry,
+                sourceKind = source.GetType().BaseType?.Name, existingTypePredicateAccepted = typeAccepted,
+                note = "Exact existing type predicate only; ownership, attachments, callbacks, generation and all root gates remain separate." };
+        }
+        var cards = simulator.State.GetPlayerCombatState(player).AllCards.ToArray();
+        var listeners = new List<object>();
+        int listenerIndex = 0;
+        string? rejected = combat.FirstRejectedHealingRootSource(source =>
+        { listeners.Add(Describe(source, "root-hook-run-gold", listenerIndex++)); return true; });
+        if (rejected is not null) throw new InvalidOperationException("Inventory unexpectedly rejected a source.");
+        var data = new {
+            root.UsesPruningComponentHealingCertificate, root.PruningComponentHealingRejection,
+            root.UsesComponentHealingCertificate, root.ComponentHealingRejection,
+            root.InitialPruningHealingUpperBound,
+            rootSourceGate = StrategicHpRecoveryBound.ComponentRootSourceRejection(simulator, player, useReviewedSources: true),
+            cards = cards.Select((c, i) => new { metadata = Describe(c.Preview, "all-combat-piles", i),
+                enchantment = c.Preview.Enchantment?.GetType().FullName, affliction = c.Preview.Affliction?.GetType().FullName,
+                growth = GrowthValues.HasTarget(c.Preview) }).ToArray(),
+            pendingReturningCards = combat.PendingReturningCards.Select((c, i) => Describe(c.Preview, "pending-return", i)).ToArray(),
+            relics = combat.RelicsOf(player).Select((s, i) => Describe(s, "branch-relic", i)).ToArray(),
+            powers = combat.EffectivePowers().Select((s, i) => Describe(s, "branch-power", i)).ToArray(),
+            enemies = combat.KnownEnemies.Select((s, i) => Describe(s.Monster!, "known-enemy", i)).ToArray(),
+            listeners,
+            stateBefore,
+            stateAfter = ContinuationStamp.CapturePredicted(player, simulator, root.StartTurnNumber, root.Forecast, root.StartTurnNumber).StateText,
+            liveState = ContinuationStamp.CaptureLive(live).StateText,
+            rootContinuationState = root.ContinuationStamp.StateText,
+            diagnosticOnly = true, newCertifications = 0,
+        };
+        File.WriteAllText(Path.Combine(outputDirectory, "all-pruning-source-inventory.json"),
+            JsonSerializer.Serialize(data, UnattendedTestFiles.JsonOptions));
+    }
+
 }

